// src/api/taskAPI.js - Centralized API calls for task management
import axios from 'axios';

const API_BASE = '/api/tasks';

// Helper to get auth headers
const getAuthHeaders = () => {
  const token = localStorage.getItem('authToken');
  return {
    headers: {
      Authorization: `Bearer ${token}`,
    },
  };
};

/**
 * getTasks - Fetches all tasks for the logged-in user
 */
export const getTasks = async () => {
  const response = await axios.get(API_BASE, getAuthHeaders());
  return response.data;
};

/**
 * createTask - Creates a new task
 * @param {Object} taskData - { title, description, priority, dueDate }
 */
export const createTask = async (taskData) => {
  const response = await axios.post(API_BASE, taskData, getAuthHeaders());
  return response.data;
};

/**
 * updateTask - Updates an existing task
 * @param {string} taskId
 * @param {Object} taskData - Fields to update
 */
export const updateTask = async (taskId, taskData) => {
  const response = await axios.put(`${API_BASE}/${taskId}`, taskData, getAuthHeaders());
  return response.data;
};

/**
 * deleteTask - Deletes a task
 * @param {string} taskId
 */
export const deleteTask = async (taskId) => {
  const response = await axios.delete(`${API_BASE}/${taskId}`, getAuthHeaders());
  return response.data;
};
